      "name": "volume_asymmetry",
      "expression": "DELTA(TS_ARGMAX($volume, 60), 5) - DELTA(TS_ARGMIN($volume, 60), 5)",
      "explanation": "measures the difference in time to peak between high and low volume eventssin a 60-day window"
    },
    {
      "name": "volume_residual_trend",
      "expression": "TS_PCT CHANGE(REGRESI($return, $volume, 60), 20)",
      "explanation": "captures the momentum of residual returns after removing volume-related trends"
    }
  ]
}

