{
  "hypothesis": "when stocks exhibit the largest 1-3 day intraday range expansion with high-low range spikes, they underperform in next-period returns",
  "factors": [
    {
      "name": "intraday_range_spike_rank",
      "expression": "RANK(TS_QUANTILE($high - $low, 20, 0.9) - RANK(T.S.MAD($high - $low, 20))",
      "explanation": "measures the cross-sectional rank of stocks with the highest intraday range spikes, using quantile-based selection and MAD normalization to isolate extreme range expansions."
    },
    {
      "name": "range_spikes_residual",
      "expression": "REGRESI($return, $high - $low, 5) - REGRESI($return, $open, 5)",
      "explanation": "captures the residual return after regressing against intraday range versus open price, isolating the portion of return unrelated to baseline price movement."
    },
    {
      "name": "asymmetric_range_gap",
      "expression": "TS.PCT.CHANGE($high - $low, 5) * (TS_ARGMAX($high, 5) - TS_ARGMIN($low, 5))",
      "explanation": "weighs range expansion by the temporal gap between daily highs and lows, emphasizing asymmetry in price behavior across time."
    },
    {
      "name": "volume_range_ratio",
      "expression": "TS.ZSCORE(($high - $low) / $volume, 20) * RANK(TS.MAD($high - $low, 20))",
      "explanation": "normalizes range per volume and ranks the magnitude of dispersion, highlighting stocks with large range but low liquidity."
    },
    {
      "name": "lagged_range_signal",
      "expression": "DELAY(RANK(TS.MAD($high - $low, 5)), 2) - RANK(TS.MAD($high - $low, 5))",
      "explanation": "compares current range dispersion ranking with a lagged version, capturing the dynamics of range expansion over time."
    }
  ]
}
